def update(self, last_done=1, total_done=None):
    if not last_done and not total_done:
        raise ValueError("Either last_done or total_done must be specified")

    if not self.started:
        self.started = True
        self.progress.desc = self.prefix
        self.progress.unpause()

    if last_done:
        self.progress.n += last_done
    else:
        self.progress.n = total_done
    self.progress.refresh()

def execute_command(command):
    """Execute a command and return its output"""

    command = shlex.split(command)
    try:
        process = subprocess.Popen(
            command,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
    except FileNotFoundError:
        raise RuntimeError("Command not found: {}".format(repr(command)))
    process.wait()
    # TODO: may use another codec to decode
    if process.returncode > 0:
        stderr = process.stderr.read().decode("utf-8")
        raise ValueError("Error executing command: {}".format(repr(stderr)))
    return process.stdout.read().decode("utf-8")

def command_pdf_to_text(output_encoding, quiet, backend, pages, source, output):

    # Define page range
    if pages:
        pages = extract_intervals(pages)

    # Define if output is file or stdout
    if output:
        output = open(output, mode="w", encoding=output_encoding)
        write = output.write
    else:
        write = click.echo
        quiet = True
    progress = not quiet

    # Download the file if source is an HTTP URL
    downloaded = False
    if source.lower().startswith("http:") or source.lower().startswith("https:"):
        result = download_file(source, progress=progress, detect=False)
        source = result.uri
        downloaded = True

    reader = rows.plugins.pdf.pdf_to_text(source, page_numbers=pages, backend=backend)
    if progress:  # Calculate total number of pages and create a progress bar
        if pages:
            total_pages = len(pages)
        else:
            total_pages = rows.plugins.pdf.number_of_pages(source, backend=backend)
        reader = tqdm(reader, desc="Extracting text", total=total_pages)

    for page in reader:
        write(page)

    if output:
        output.close()
    if downloaded:
        os.unlink(source)

def value_error(value, cls):
    value = repr(value)
    if len(value) > 50:
        value = value[:50] + "..."
    raise ValueError("Value '{}' can't be {}".format(value, cls.__name__))

def deserialize(cls, value, *args, **kwargs):
    if value is not None:
        if isinstance(value, six.binary_type):
            return value
        elif isinstance(value, six.text_type):
            try:
                return b64decode(value)
            except (TypeError, ValueError, binascii.Error):
                raise ValueError("Can't decode base64")
        else:
            value_error(value, cls)
    else:
        return b""

def deserialize(cls, value, *args, **kwargs):
    value = super(BoolField, cls).deserialize(value)
    if value is None or isinstance(value, cls.TYPE):
        return value

    value = as_string(value).lower()
    if value in cls.TRUE_VALUES:
        return True
    elif value in cls.FALSE_VALUES:
        return False
    else:
        raise ValueError("Value is not boolean")

def deserialize(cls, value, *args, **kwargs):
    value = super(IntegerField, cls).deserialize(value)
    if value is None or isinstance(value, cls.TYPE):
        return value
    elif isinstance(value, float):
        new_value = int(value)
        if new_value != value:
            raise ValueError("It's float, not integer")
        else:
            value = new_value

    value = as_string(value)
    if value != "0" and value.startswith("0"):
        raise ValueError("It's string, not integer")
    return int(value) if SHOULD_NOT_USE_LOCALE else locale.atoi(value)

def deserialize(cls, value, *args, **kwargs):
