def _valid_table_name(name):
    """Verify if a given table name is valid for `rows`.

    Rules:
    - Should start with a letter or '_'
    - Letters can be capitalized or not
    - Acceps letters, numbers and _
    """
    if name[0] not in "_" + string.ascii_letters or not set(name).issubset(
        "_" + string.ascii_letters + string.digits
    ):
        return False

    else:
        return True

def locale_context(name, category=locale.LC_ALL):

    old_name = locale.getlocale()
    if None not in old_name:
        old_name = ".".join(old_name)
    if isinstance(name, six.text_type):
        name = str(name)

    if old_name != name:
        locale.setlocale(category, name)

    rows.fields.SHOULD_NOT_USE_LOCALE = False
    try:
        yield
    finally:
        if old_name != name:
            locale.setlocale(category, old_name)

    rows.fields.SHOULD_NOT_USE_LOCALE = True

