def get_delimiter_function(value):
    if isinstance(value, str):  # regular string, match exactly
        return lambda obj: (isinstance(obj, TextObject) and obj.text.strip() == value)

    elif hasattr(value, "search"):  # regular expression
        return lambda obj: bool(
            isinstance(obj, TextObject) and value.search(obj.text.strip())
        )

    elif callable(value):  # function
        return lambda obj: bool(value(obj))

def add(self, obj):
    self.objects.append(obj)
    d0 = getattr(obj, self.dimension_0)
    d1 = getattr(obj, self.dimension_1)
    if d0 < self.minimum:
        self.minimum = d0
    if d1 > self.maximum:
        self.maximum = d1

def group_objects(objs, threshold, axis):
    if axis == "x":
        GroupClass = VerticalGroup
    elif axis == "y":
        GroupClass = HorizontalGroup

    groups = []
    for obj in objs:
        found = False
        for group in groups:
            if group.contains(obj):
                group.add(obj)
                found = True
                break
        if not found:
            group = GroupClass(threshold=threshold)
            group.add(obj)
            groups.append(group)
    return {group.minimum: group.objects for group in groups}

def table_bbox(self):
    groups = group_objects(self.text_objects, self.y_threshold, "y")
    desired_objs = []
    for group_objs in groups.values():
        if len(group_objs) < 2:  # Ignore floating text objects
            continue
        desired_objs.extend(group_objs)
    if not desired_objs:
        return (0, 0, 0, 0)
    x_min = min(obj.x0 for obj in desired_objs)
    x_max = max(obj.x1 for obj in desired_objs)
    y_min = min(obj.y0 for obj in desired_objs)
    y_max = max(obj.y1 for obj in desired_objs)
    return (x_min, y_min, x_max, y_max)

def selected_objects(self):
    """Filter out objects outside table boundaries"""

    return [
        obj
        for obj in self.text_objects
        if contains_or_overlap(self.table_bbox, obj.bbox)
    ]

def _define_intervals(objs, min_attr, max_attr, threshold, axis):
    groups = group_objects(objs, threshold, axis)

    intervals = [
        (key, max_attr(max(value, key=max_attr))) for key, value in groups.items()
    ]
    intervals.sort()
    if not intervals:
        return []

    # Merge overlapping intervals
    result = [intervals[0]]
    for current in intervals[1:]:
        previous = result.pop()
        if current[0] <= previous[1] or current[1] <= previous[1]:
            result.append((previous[0], max((previous[1], current[1]))))
        else:
            result.extend((previous, current))
    return result

def x_intervals(self):
    objects = self.selected_objects
    objects.sort(key=lambda obj: obj.x0)
    return self._define_intervals(
        objects,
        min_attr=lambda obj: obj.x0,
        max_attr=lambda obj: obj.x1,
        threshold=self.x_threshold,
        axis="x",
    )

def y_intervals(self):
    objects = self.selected_objects
    objects.sort(key=lambda obj: -obj.y1)
    return self._define_intervals(
        objects,
        min_attr=lambda obj: obj.y0,
        max_attr=lambda obj: obj.y1,
        threshold=self.y_threshold,
        axis="y",
    )

def get_lines(self):
    x_intervals = list(self.x_intervals)
    if self.x_order == -1:
        x_intervals = list(reversed(x_intervals))
    y_intervals = list(self.y_intervals)
    if self.y_order == -1:
        y_intervals = list(reversed(y_intervals))
    objs = list(self.selected_objects)

    matrix = []
    for y0, y1 in y_intervals:
        line = []
        for x0, x1 in x_intervals:
            cell = [
                obj for obj in objs if x0 <= obj.x0 <= x1 and y0 <= obj.y0 <= y1
            ]
            if not cell:
                line.append(None)
            else:
                line.append(cell)
                for obj in cell:
                    objs.remove(obj)
        matrix.append(line)
    return matrix

def _clean_intersections(lines):
    def other_line_contains(all_lines, search_line):
        for line2 in all_lines:
            if search_line == line2:
                continue
            elif search_line[0] >= line2[0] and search_line[1] <= line2[1]:
                return True
        return False

    final = []
    for line in lines:
        if not other_line_contains(lines, line):
            final.append(line)
    return final

def x_intervals(self):
    x_intervals = set((obj.x0, obj.x1) for obj in self.rects)
    return sorted(self._clean_intersections(x_intervals))

def y_intervals(self):
    y_intervals = set((obj.y0, obj.y1) for obj in self.rects)
    return sorted(self._clean_intersections(y_intervals))

def other_line_contains(all_lines, search_line):
    for line2 in all_lines:
        if search_line == line2:
            continue
        elif search_line[0] >= line2[0] and search_line[1] <= line2[1]:
            return True
    return False

def _parse_frame_style(frame_style):
    if frame_style is None:
        frame_style = "None"
    try:
        FRAMES[frame_style.lower()]
    except KeyError:
        raise ValueError(
            "Invalid frame style '{}'. Use one of 'None', "
            "'ASCII', 'single' or 'double'.".format(frame_style)
        )
    return frame_style

def _guess_frame_style(contents):
    first_line_chars = set(contents.split("\n")[0].strip())
    for frame_style, frame_dict in FRAMES.items():
        if first_line_chars <= set(frame_dict.values()):
            return frame_style
    return "None"

def _cell_to_python(cell):
    """Convert a PyOpenXL's `Cell` object to the corresponding Python object."""
    data_type, value = cell.data_type, cell.value

    if type(cell) is EmptyCell:
        return None
    elif data_type == "f" and value == "=TRUE()":
        return True
    elif data_type == "f" and value == "=FALSE()":
        return False

    elif cell.number_format.lower() == "yyyy-mm-dd":
        return str(value).split(" 00:00:00")[0]
    elif cell.number_format.lower() == "yyyy-mm-dd hh:mm:ss":
        return str(value).split(".")[0]

    elif cell.number_format.endswith("%") and isinstance(value, Number):
        value = Decimal(str(value))
        return "{:%}".format(value)

    elif value is None:
        return ""
    else:
        return value

def cell_value(sheet, row, col):
    """Return the cell value of the table passed by argument, based in row and column."""
    cell = sheet.cell(row, col)
    field_type = CELL_TYPES[cell.ctype]

    # TODO: this approach will not work if using locale
    value = cell.value

    if field_type is None:
        return None

    elif field_type is fields.TextField:
        if cell.ctype != xlrd.XL_CELL_BLANK:
            return value
        else:
            return ""

    elif field_type is fields.DatetimeField:
        time_tuple = xlrd.xldate_as_tuple(value, sheet.book.datemode)
        value = field_type.serialize(datetime.datetime(*time_tuple))
        return value.split("T00:00:00")[0]

    elif field_type is fields.BoolField:
        if value == 0:
            return False
        elif value == 1:
            return True

    elif cell.xf_index is None:
        return value  # TODO: test

    else:
        book = sheet.book
        xf = book.xf_list[cell.xf_index]
        fmt = book.format_map[xf.format_key]

        if fmt.format_str.endswith("%"):
            # TODO: we may optimize this approach: we're converting to string
            # and the library is detecting the type when we could just say to
            # the library this value is PercentField

            if value is not None:
                try:
                    decimal_places = len(fmt.format_str[:-1].split(".")[-1])
                except IndexError:
                    decimal_places = 2
                return "{}%".format(str(round(value * 100, decimal_places)))
            else:
                return None

        elif type(value) == float and int(value) == value:
            return int(value)

        else:
            return value

def get_table_start(sheet):
    empty_cell_type = xlrd.empty_cell.ctype
    start_column, start_row = 0, 0
    for col in range(sheet.ncols):
        if any(cell for cell in sheet.col(col) if cell.ctype != empty_cell_type):
            start_column = col
            break
    for row in range(sheet.nrows):
        if any(cell for cell in sheet.row(row) if cell.ctype != empty_cell_type):
            start_row = row
            break
    return start_row, start_column

def complete_with_None(lists, size):
    for element in lists:
        element.extend([None] * (size - len(element)))
        yield element

def import_from_ods(filename_or_fobj, index=0, *args, **kwargs):
    # TODO: import spreadsheet by name
    # TODO: unescape values

    filename, _ = get_filename_and_fobj(filename_or_fobj)

    ods_file = zipfile.ZipFile(filename)
    content_fobj = ods_file.open("content.xml")
    xml = content_fobj.read()  # will return bytes
    content_fobj.close()

    document = xml_from_string(xml)
    namespaces = document.nsmap
    spreadsheet = document.xpath("//office:spreadsheet", namespaces=namespaces)[0]
    tables = xpath(spreadsheet, "//table:table", namespaces)
    table = tables[index]

    table_rows_obj = xpath(table, "//table:table-row", namespaces)
    table_rows = []
    for row_obj in table_rows_obj:
        row = []
        for cell in xpath(row_obj, "//table:table-cell", namespaces):
            children = cell.getchildren()
            if not children:
                continue

            # TODO: evalute 'boolean' and 'time' types
            value_type = attrib(cell, namespaces["office"], "value-type")
            if value_type == "date":
                cell_value = attrib(cell, namespaces["office"], "date-value")
            elif value_type == "float":
                cell_value = attrib(cell, namespaces["office"], "value")
            elif value_type == "percentage":
                cell_value = attrib(cell, namespaces["office"], "value")
                cell_value = Decimal(cell_value)
                cell_value = "{:%}".format(cell_value)
            elif value_type == "string":
                try:
                    # get computed string (from formula, for example)
                    cell_value = attrib(cell, namespaces["office"], "string-value")
                except KeyError:
                    # computed string not present => get from <p>...</p>
                    cell_value = children[0].text
            else:  # value_type == some type we don't know
                cell_value = children[0].text

            try:
                repeat = attrib(cell, namespaces["table"], "number-columns-repeated")
            except KeyError:
                row.append(cell_value)
            else:
                for _ in range(int(repeat)):
                    row.append(cell_value)

        if row:
            table_rows.append(row)

    max_length = max(len(row) for row in table_rows)
    full_rows = complete_with_None(table_rows, max_length)
    meta = {"imported_from": "ods", "filename": filename}
    return create_table(full_rows, meta=meta, *args, **kwargs)
